class Widget {
  constructor(public width: number, public height: number) {}
  clone(): Widget {
    return Object.assign(Object.create(Object.getPrototypeOf(this)), this);
  }
}
const original = new Widget(100, 200);
const copy = original.clone();

class Payment {
  constructor(public amount:number, public db:DbConnection) {}
  clone(): Payment {
    return Object.assign(Object.create(Object.getPrototypeOf(this)), this);
  }
}
const sharedDb = new DbConnection();
const proto = new Payment(0, sharedDb);
const p = proto.clone();
p.amount = 100;

// Version A: clone a configured prototype
class Task {
  constructor(public name:string, public db:Db) {}
  clone() { return Object.assign(Object.create(Object.getPrototypeOf(this)), this); }
}
const proto = new Task('import', sharedDb);
function createTaskA() { return proto.clone(); }

// Version B: build per-request instance
function createTaskB(name:string, db:Db) {
  return new Task(name, db);
}
